css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .62); position: relative; }
.loader .wall { position: absolute; inset: 0; border-radius: 7px; background: color-mix(in srgb, var(--accent) 12%, transparent); }
.loader .stripe { position: absolute; left: 6%; top: 40%; height: 28%; width: 0; border-radius: 3px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); animation: paint-fill calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader .roller { position: absolute; top: 36%; left: 6%; width: 15%; height: 36%; border-radius: 4px; background: linear-gradient(var(--accent-2), var(--accent)); animation: paint-move calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader .roller::after { content: ''; position: absolute; left: 38%; bottom: 96%; width: 16%; height: 62%; border-radius: 2px; background: #94a3b8; }
@keyframes paint-fill { 0% { width: 0; opacity: 1; } 55%, 70% { width: 88%; opacity: 1; } 94%, 100% { width: 88%; opacity: 0; } }
@keyframes paint-move { 0% { left: 6%; } 55%, 70% { left: 79%; } 100% { left: 6%; } }
